namespace ghidra.file.formats.ios.generic;

using ghidra.app.services;
using ghidra.app.util.importer;
using ghidra.program.model.address;
using ghidra.program.model.lang;
using ghidra.program.model.lang;
using ghidra.program.model.listing;
using ghidra.program.model.mem;
using ghidra.program.model.mem;
using ghidra.program.model.symbol;
using ghidra.util.exception;
using ghidra.util.task;

public class iOS_FixupArmSymbolsAnalyzer : AbstractAnalyzer {

	private static readonly string NAME = "Apple iOS ARM Symbol Fixup";
	private static readonly string DESCRIPTION =
		"Moves the pre-defined ARM symbols to image base of the iOS binary.";

	public iOS_FixupArmSymbolsAnalyzer() : base(NAME, DESCRIPTION, AnalyzerType.BYTE_ANALYZER)
    {
		setSupportsOneTimeAnalysis();
		setPriority(AnalysisPriority.FORMAT_ANALYSIS);
	}

	/* @Override */
	public bool getDefaultEnablement(Program program) {
		return isBoot(program);
	}

	/* @Override */
	public bool canAnalyze(Program program) {
		return isBoot(program);
	}

	/* @Override */
	public bool added(Program program, AddressSetView set, TaskMonitor monitor, MessageLog log)
    {

		SymbolTable symbolTable = program.getSymbolTable();
		SymbolIterator symbolIterator = symbolTable.getSymbolIterator();
		while (symbolIterator.hasNext()) {
			Symbol symbol = symbolIterator.next();
			if (symbol.isPinned()) {
				symbol.setPinned(false);
			}
		}
		return false;
	}

	private bool isBoot(Program program) {
		if (program == null) {
			return false;
		}
		Language language = program.getLanguage();
		if (language == null) {
			return false;
		}
		Processor processor = language.getProcessor();
		if (processor == null) {
			return false;
		}
		if (!processor.equals(Processor.findOrPossiblyCreateProcessor("ARM"))) {
			return false;
		}

		Address minAddress = program.getMinAddress();
		if (minAddress == null) {//program has 0 memory blocks
			return false;
		}

		Address address = null;
		try {
			address = minAddress.add(0x200);
		}
		catch (Exception e) {
			return false;//program memory is too small
		}
		if (address == null) {
			return false;
		}

		Memory memory = program.getMemory();
		byte[] bytes = new byte[0x40];
		try {
			memory.getBytes(address, bytes);
		}
		catch (MemoryAccessException e) {
		}

		string string = new string(bytes).trim();

		if (string.indexOf("Apple") != -1) {
			if (string.startsWith("SecureROM")) {
				return true;
			}
			if (string.startsWith("LLB")) {
				return true;
			}
			if (string.startsWith("iBoot")) {
				return true;
			}
			if (string.startsWith("iBEC")) {
				return true;
			}
			if (string.startsWith("iBSS")) {
				return true;
			}
		}

		return false;
	}
}
